class Solution:
    def nthBeat(self, n: int, a: int, b: int) -> int:
        next_a, next_b = a, b
        beat = 0
        for _ in range(n):
            beat = min(next_a, next_b)
            if next_a == beat:
                next_a += a
            if next_b == beat:
                next_b += b
        return beat % (10**9 + 7)

