import math

class Solution:
    def nthBeat(self, n: int, a: int, b: int) -> int:
        lcm = a // math.gcd(a, b) * b
        lo, hi = 1, n * min(a, b)
        while lo < hi:
            mid = (lo + hi) // 2
            if mid // a + mid // b - mid // lcm >= n:
                hi = mid
            else:
                lo = mid + 1
        return lo % (10**9 + 7)

